import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷四·21","description":"易小帖 - 卷四·21","frontmatter":{"title":"卷四·21","description":"易小帖 - 卷四·21"},"headers":[],"relativePath":"zh/classics/yixiaotie/115.md","filePath":"zh/classics/yixiaotie/115.md"}'),o={name:"zh/classics/yixiaotie/115.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷四·21",tabindex:"-1"},[r("卷四·21 "),e("a",{class:"header-anchor",href:"#卷四·21","aria-label":"Permalink to “卷四·21”"},"​")],-1),e("p",null,"乃若九六七八，用之揲筮之法則人各為說，亦各有是處，而不能盡合。崔憬曰：《說卦》雲：「幽贊於神明而生蓍，參天兩地而倚數，此大衍之法也。」但其所雲參天者，謂陽從三始，自三而順數之，而五而七而九，不取於一也。兩地者，謂陰從兩始，自二而逆數之，而十而八而六，不取於四也。惟陽極於九，故九為老陽，陰極於六，故六為老陰。九六者，乾坤二卦之策也。而於是以次推之，則七為長陽為震，八為長陰為巽，五為中陽為坎，十為中陰為離，三為少陽為艮，二為少陰為兌，而長陽數七，則七七四十九而為蓍圓。長陰數八，則八八六十四而為卦方。而一四不用，則合天數地數五十有五，而剛用五十，此固大衍之數之可稽者。然以之衍蓍，則止有九六七八，而並無五十，三二且止，當以九六為老，七八為少，而中長分配並無所用。於是一行則又為說曰：蓍以少為陽，以多為陰，一變之揲，非五則九，二三變之揲，非四則八。然而遇五與四則為陽以少也，遇九與八則為陰以多也。使三變而得一五兩四，為十三數，則三變皆陽，老陽也。老陽十三策，則其餘策以四揲之，適得九個四，是九也。使三變而得一九兩八，為二十五數，則三變皆陰，老陰也。老陰二十五策，則其餘策以四揲之，適得六個四，是六也。使三變而得一五兩八，為二十一數，則兩陰一陽，少陽也。少陽二十一策，則其餘策以四揲之，適得七個四，是七也。使三變而得一八兩五，為十八數，則兩陽一陰，少陰也。少陰十八策，則其餘策以四揲之，適得八個四，是八也。其於揲筮之法，亦雲至密而終未合者，以七八皆餘數而非正數也。且所餘皆四，所餘皆偶數，而徒以六七八九乘之，此乘數並非餘數也。乃郭子和則又為說曰：乾策二百一十六，以六爻六分之，每一爻得三十六，而又四分之，即九也。坤策百四十有四，亦以六爻六分之，每一爻得二十四，而又四分之，即六也。此九六之說也。然而七八無有也。乃又為說曰：二篇之策，陽爻百九十有二，以三十六乘之，積六千九百十有二。陰爻百九十有二，以二十四乘之，積四千六百八，合之為萬有一千五百二十。則二篇之策，亦祗有九六，而七八無有，乃即此陽爻百九十有二，以少陽二十八乘之，積五千三百七十六，即此陰爻百九十有二，以少陰三十二乘之，積六千一百四十四，合之亦為萬有一千五百二十，是祗此二篇之策，而九六七八皆有合焉。然而七八積數同於九六，此即暮四朝三之術，猶之九六合十五，七八亦合十五，老少不分，不可訓也。若朱元晦遵陳摶之說，謂兩儀所生四象，即老少陰陽，以老陽居東第一位，少陰居東第二位，少陽居西第三位，老陰居西第四位，遂謂老陽居一則餘九，少陰居二則餘八，少陽居三則餘七，老陰居四則餘六，以為至巧，然仍以所餘為所衍之數。竊崔憬一行二法，而又自造為一二三四之位。夫伏羲畫卦，未嘗北面，而乃畫從東起，是左手畫也。且少二之女，何得先老四之母，至再加一畫，而乾一震二巽五坤八，則又與乾坤九六，六子七八之說盡反不合。惟先仲氏曰：此參天兩地也。畫卦者，始於一而成於三，惟乾參天，故三其三而得九，此老陽也，三畫也。惟坤兩地，故兩其三而得六，此老陰也，六畫也。而於是以一三而兩兩者為七，為三男，則震也坎也艮也，皆七畫也，少陽也。以兩三而一兩者為八，為三女，則巽也離也兌也，皆八畫也，少陰也。是以數而言，皆正數，非餘數也，亦皆揲數，非乘揲之數也。以位而言，則有老少而無長中，較之六子六位，摘去其四者，何等也。有九六七八，而無五十，三二較之生成十位，無故而捨六不用，又何等也。此簡易法也。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
